package cn.lili.modules.community.p0.stage45;
import org.junit.jupiter.api.Test;
import java.time.Instant;import java.util.*;
import static cn.lili.modules.community.p0.support.Stage1Json.*;
import static org.junit.jupiter.api.Assertions.*;
class Stage45ChannelCapabilitiesTest {
 static final Instant NOW=Instant.parse("2026-11-03T03:00:00Z");
 Map<String,Object> row(){return map("mode","MOCK","payment_appid","S45_TEST_APP","last_sync_state","SUCCESS","verified_at",NOW.minusSeconds(60),"application_state","COMPLETED","capability_evidence",write(map("sourceMode","MOCK","paymentAppId","S45_TEST_APP","verificationState","VERIFIED","paymentEnabled",true,"profitsharingEnabled",true)));}
 String status(Map<String,Map<String,Object>> checks,String key){return (String)checks.get(key).get("status");}
 @Test void missingRefundReturnAndBillEvidenceDoesNotInheritVerifiedOnboarding(){var checks=Stage45Channels.capabilityChecks(row(),NOW);assertEquals("MOCK_READY",status(checks,"onboarding"));assertEquals("MOCK_READY",status(checks,"payment"));assertEquals("MOCK_READY",status(checks,"profitsharing"));for(String k:List.of("refund","return","bill")){assertEquals("EVIDENCE_PENDING",status(checks,k));assertNull(checks.get(k).get("verifiedAt"));}}
 @Test void sixCapabilitiesCanHoldDifferentFactsWithoutLiftingUnknownOrRestricted(){var r=row();r.put("capability_evidence",write(map("sourceMode","MOCK","paymentAppId","S45_TEST_APP","verificationState","VERIFIED","paymentEnabled",true,"profitsharingEnabled",false,"refundEnabled",true,"billEnabled",false)));var c=Stage45Channels.capabilityChecks(r,NOW);assertEquals(List.of("MOCK_READY","MOCK_READY","RESTRICTED","MOCK_READY","EVIDENCE_PENDING","RESTRICTED"),c.values().stream().map(x->x.get("status")).toList());assertEquals(NOW.minusSeconds(60),c.get("refund").get("verifiedAt"));assertFalse(c.get("bill").get("reason").toString().isBlank());}
 @Test void wrongModeOrApplicationCannotSupplyOtherCapabilityEvidence(){for(String field:List.of("sourceMode","paymentAppId")){var r=row();var e=object(r.get("capability_evidence"));e.addProperty(field,"WRONG");r.put("capability_evidence",write(e));var c=Stage45Channels.capabilityChecks(r,NOW);for(String k:List.of("payment","profitsharing","refund","return","bill"))assertEquals("EVIDENCE_PENDING",status(c,k));}}
 @Test void failedLatestQueryPreservesKnownFactsButDoesNotDeclareCurrentReady(){var r=row();r.put("last_sync_state","UNKNOWN");var c=Stage45Channels.capabilityChecks(r,NOW);assertEquals("STALE",status(c,"payment"));assertEquals("MOCK_READY",c.get("payment").get("lastKnownStatus"));assertEquals("EVIDENCE_PENDING",status(c,"refund"));assertEquals(NOW.minusSeconds(60),c.get("payment").get("verifiedAt"));}
 @Test void expiredOrFutureEvidenceRequiresFreshVerification(){for(var time:List.of(NOW.minusSeconds(86400),NOW.plusSeconds(1))){var r=row();r.put("verified_at",time);assertEquals("STALE",status(Stage45Channels.capabilityChecks(r,NOW),"payment"));}}
 @Test void unverifiedNativeResponseDoesNotBecomeAnExplicitCapabilityFact(){var r=row();var e=object(r.get("capability_evidence"));e.addProperty("verificationState","UNVERIFIED");r.put("capability_evidence",write(e));assertEquals("EVIDENCE_PENDING",status(Stage45Channels.capabilityChecks(r,NOW),"payment"));}
 @Test void realRecordCannotBePresentedAsMockReady(){var r=row();r.put("mode","REAL");var e=object(r.get("capability_evidence"));e.addProperty("sourceMode","REAL");r.put("capability_evidence",write(e));var c=Stage45Channels.capabilityChecks(r,NOW);assertEquals("VERIFIED",status(c,"payment"));assertTrue(c.values().stream().noneMatch(x->"MOCK_READY".equals(x.get("status"))));}
 @Test void projectionDoesNotModifyOriginalNativeEvidence(){var r=row();String before=write(r);Stage45Channels.capabilityChecks(r,NOW);assertEquals(before,write(r));}
}
